"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type MarqueeProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** The words: each child is one word or phrase in the band. */
  children: React.ReactNode
  /**
   * band: display words, each closed by a full stop, cropped by the frame's ends.
   * ticker: small capitals running between two hairlines.
   * counter: two rows of the band cropped against each other, running opposite ways.
   */
  variant?: "band" | "ticker" | "counter"
  /** How far the words travel for each pixel the page scrolls. */
  speed?: number
  /** Travel towards the start as you scroll down, instead of reading along towards the end. */
  reverse?: boolean
  /** Names the list of words for readers. */
  label?: string
}

/**
 * A band of words that moves only with the page's scroll. Its offset is read from where the band stands in the view,
 * so it stops the moment the scroll stops, runs back when you scroll back, and keeps step with smooth scrolling.
 * The first run of words is the list readers get; the copies that fill the band are hidden from them.
 */
function Marquee({ children, variant = "band", speed = 0.4, reverse = false, label, className, ...props }: MarqueeProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [copies, setCopies] = React.useState(2)
  const words = React.Children.toArray(children)

  React.useEffect(() => {
    const el = ref.current
    const run = el?.querySelector<HTMLElement>(".db-marquee-words")
    if (!el || !run || matchMedia("(prefers-reduced-motion: reduce)").matches) return // the words wrap and stand still
    let period = 0, frame = 0
    // How far the band has risen through the view, times the speed, wrapped to one run of words. Read from the real
    // layout in a frame asked for by the scroll event, which runs after a smooth scroller's own frame.
    const read = () => {
      if (!period) return
      const travelled = (innerHeight - el.getBoundingClientRect().top) * speed
      el.style.setProperty("--o", `${((travelled % period) + period) % period}px`)
    }
    const measure = () => {
      period = run.offsetWidth // one run, its trailing gap included: a new face or size changes it
      el.style.setProperty("--period", `${period}px`)
      if (period) setCopies(Math.max(2, Math.ceil(el.clientWidth / period) + 1))
      read()
    }
    const onScroll = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(read)
    }
    const resized = new ResizeObserver(measure)
    resized.observe(el)
    resized.observe(run)
    addEventListener("scroll", onScroll, { passive: true })
    return () => {
      cancelAnimationFrame(frame)
      resized.disconnect()
      removeEventListener("scroll", onScroll)
    }
  }, [speed])

  const rows = variant === "counter" ? 2 : 1
  return (
    <div ref={ref} data-slot="marquee" data-variant={variant === "band" ? undefined : variant} className={cn("db-marquee", className)} {...props}>
      {Array.from({ length: rows }, (_, row) => (
        <div key={row} className="db-marquee-row" data-back={reverse !== (row === 1) || undefined}>
          <div className="db-marquee-track">
            {Array.from({ length: copies }, (_, copy) => {
              const read = row === 0 && copy === 0
              return (
                <ul key={copy} className="db-marquee-words" aria-label={read ? label : undefined} aria-hidden={read ? undefined : true} inert={!read}>
                  {words.map((word, i) => (
                    <li key={i}>{word}</li>
                  ))}
                </ul>
              )
            })}
          </div>
        </div>
      ))}
    </div>
  )
}

export { Marquee, type MarqueeProps }

@layer components {
  /* ── db-marquee ── a band of words that moves only with the page's scroll. --o is how far it has travelled, wrapped
     to one run of words (--period); the copies after the first fill the band and are hidden from readers. It never
     moves by itself: when the scroll stops, it stands. Pass a dynamic class (db-fff, db-ff…) for the size. */
  .db-marquee { --db-marquee-dir: 1; --db-marquee-gap: 0.32em; --o: 0px; --period: 0px; display: grid; overflow: clip; font-weight: 300; color: var(--db-ink); }
  .db-marquee:is([dir="rtl"], [dir="rtl"] *) { --db-marquee-dir: -1; } /* reading along runs the other way */
  .db-marquee-row { overflow: clip; }
  .db-marquee-track { display: flex; inline-size: max-content; translate: calc(var(--o) * -1 * var(--db-marquee-dir)) 0; }
  .db-marquee-row[data-back] .db-marquee-track { translate: calc((var(--o) - var(--period)) * var(--db-marquee-dir)) 0; }
  .db-marquee-words { display: flex; gap: var(--db-marquee-gap); margin: 0; padding: 0 var(--db-marquee-gap) 0 0; list-style: none; white-space: nowrap; }
  .db-marquee-words:is([dir="rtl"] *) { padding: 0 0 0 var(--db-marquee-gap); }
  .db-marquee-words > li { margin: 0; }
  /* band: after "Renaissance." and "Less is more.", every word a statement closed by its full stop. */
  .db-marquee:not([data-variant="ticker"]) .db-marquee-words > li::after { content: "."; }

  /* ticker: small capitals running between two hairlines, after the Renaissance poster's top row and the frame row of
     SHAPES / GRADIENTS. */
  .db-marquee[data-variant="ticker"] {
    --db-marquee-gap: var(--db-space-7);
    border-block: var(--db-hairline) solid var(--db-rule); padding-block: var(--db-space-3);
    font: 500 var(--db-pp) / var(--db-pp-lh) var(--db-voice); letter-spacing: 0.08em; text-transform: uppercase; color: var(--db-graphite);
  }

  /* counter: SPECTRA's two rows, the upper cut at its head and the lower at its feet, facing each other across one
     hairline and running opposite ways. Each word's box is trimmed to its cap height and baseline, so the cuts fall
     on the letters themselves in every face: into the capitals above, along the baseline below (the full stops stay). */
  .db-marquee[data-variant="counter"] .db-marquee-row { overflow: visible; }
  .db-marquee[data-variant="counter"] .db-marquee-words > li { text-box: trim-both cap alphabetic; }
  .db-marquee[data-variant="counter"] .db-marquee-row:first-child { clip-path: inset(0 0 -1em 0); padding-block-end: 0.28em; }
  .db-marquee[data-variant="counter"] .db-marquee-row:first-child .db-marquee-track { margin-block-start: -0.16em; }
  .db-marquee[data-variant="counter"] .db-marquee-row + .db-marquee-row { clip-path: inset(-1em 0 0 0); padding-block-start: 0.14em; border-block-start: var(--db-hairline) solid var(--db-rule-strong); }

  /* Reduced motion: the words stand still and wrap, whole, as one list. */
  @media (prefers-reduced-motion: reduce) {
    .db-marquee-track { inline-size: auto; translate: none; }
    .db-marquee-row[data-back] .db-marquee-track { translate: none; }
    .db-marquee-words { flex-wrap: wrap; white-space: normal; padding: 0; }
    .db-marquee-words + .db-marquee-words, .db-marquee-row + .db-marquee-row { display: none; }
    .db-marquee-words { row-gap: 0; }
    .db-marquee[data-variant="counter"] .db-marquee-row:first-child { clip-path: none; padding: 0; }
    .db-marquee[data-variant="counter"] .db-marquee-row:first-child .db-marquee-track { margin-block: 0; }
    .db-marquee[data-variant="counter"] .db-marquee-words > li { text-box: normal; }
  }
}
